const MarkdownRenderer=React.lazy(async()=>{const[{default:ReactMarkdown},{default:remarkGfm}]=await Promise.all([import('react-markdown'),import('remark-gfm')]);return{default:({content}:{content:string})=><div className="markdown-body"><ReactMarkdown remarkPlugins={[remarkGfm]} skipHtml>{content}</ReactMarkdown></div>};});
function Markdown({content}:{content:string}){return <React.Suspense fallback={<p className="text-sm text-slate-500">正在载入富文本…</p>}><MarkdownRenderer content={content}/></React.Suspense>;}
const brand='/brand/';
function agentSkillText(apiKey:string,key?:any){return `# 医疗大健康需求平台 Agent 技能

你可以使用医疗大健康需求平台的案例与需求 API。

- API 地址：${window.location.origin}/api
- 认证方式：请求头 \`Authorization: Bearer ${apiKey}\`
- 权限范围：${key?.scopes?.join('、')??'以服务端授权为准'}；到期时间：${key?.expiresAt?new Date(key.expiresAt*1000).toLocaleString('zh-CN'):'请在密钥管理页确认'}。\n- 仅执行已获授权的操作；403 表示超出范围，请停止并请用户检查授权。\n- 浏览案例：GET \`/cases\`；查看案例：GET \`/cases/{id}\`
- 若具备 requirements:write，提交需求：POST \`/requirements\`，JSON 至少包含 \`title\`、\`content\`；只有用户明确同意公开时才设置 \`shareConsent: true\`。
- 不要将 API Key 分享给其他人，也不要提交到代码仓库。
- 请求失败时说明接口返回的错误，并先确认登录态或密钥状态。`;}

function Landing(){return <div className="min-h-screen bg-[#fffdf9] text-slate-900"><header className="border-b border-orange-100 bg-white/90"><div className="mx-auto max-w-7xl px-5 h-[72px] flex items-center justify-between"><Link to="/" className="flex items-center gap-3 font-semibold text-lg"><img src={brand+'mascot.webp'} className="h-11 w-11 object-cover object-top rounded-full bg-orange-100" alt="工作坊吉祥物"/>医疗大健康需求平台 <span className="hidden sm:block text-sm font-normal text-slate-500">需求与案例平台</span></Link><div className="flex gap-3 items-center"><Link to="/login" className="text-sm text-slate-600 hover:text-orange-600">登录</Link><Link to="/register" className="bg-orange-500 hover:bg-orange-600 text-white rounded-lg px-4 py-2 text-sm font-medium">免费注册</Link></div></div></header><main><section className="max-w-7xl mx-auto grid lg:grid-cols-2 items-center gap-8 px-6 py-14 lg:py-24"><div className="space-y-6"><span className="inline-flex rounded-full border border-orange-200 bg-orange-50 text-orange-700 px-4 py-1.5 text-xs font-medium">Powered by 杰哥AI工作坊</span><h1 className="text-4xl md:text-5xl lg:text-6xl font-bold tracking-tight leading-tight md:leading-none">医疗大健康，<br/><span className="text-orange-600">从真实问题出发。</span></h1><p className="text-lg text-slate-600 leading-relaxed max-w-xl">面向医药流通、医院与健康服务、IVD 等领域，记录真实问题、整理需求材料，结合业务场景与 AI 一起澄清需求。</p><div className="flex flex-wrap gap-3"><Link to="/register" className="px-6 py-3 rounded-lg bg-orange-500 text-white font-medium hover:bg-orange-600">开始探索案例 →</Link><Link to="/login" className="px-6 py-3 rounded-lg border border-slate-200 bg-white font-medium hover:border-orange-300">我已有账号</Link></div><p className="text-sm text-slate-500">注册即可浏览案例、提交需求并获得专属 API Key。</p></div><div className="relative"><div className="absolute inset-5 rounded-[3rem] bg-orange-100/60 blur-3xl"/><img src={brand+'mascot.webp'} className="relative mx-auto w-full max-w-md rounded-2xl object-contain" alt="医疗大健康及医药领域需求平台"/></div></section><section className="bg-white border-y border-orange-100"><div className="max-w-7xl mx-auto px-6 py-16"><div className="mb-9"><h2 className="text-2xl md:text-3xl font-semibold">从一个问题，到下一个可复用的案例</h2><p className="mt-2 text-slate-500">记录业务问题，保留参考材料，逐步澄清适合当前场景的需求。</p></div><div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-4">{[['01','提交需求','用 Markdown 描述业务问题，上传多份参考资料。'],['02','脱敏审核','清除敏感信息，保护企业数据。'],['03','案例沉淀','按行业和业务分类整理公开案例。'],['04','交给 AI 探索','下载需求与 Agent 材料，结合实际场景讨论。']].map(([n,t,d])=><div className="border border-slate-200 rounded-2xl p-6" key={n}><span className="text-orange-500 text-sm font-semibold">{n}</span><h3 className="font-semibold text-lg mt-3">{t}</h3><p className="text-slate-500 text-sm mt-2 leading-relaxed">{d}</p></div>)}</div></div></section><section className="max-w-7xl mx-auto px-6 py-16 grid md:grid-cols-[1fr_240px] items-center gap-8"><div><h2 className="text-2xl font-semibold">准备好记录你的第一个需求了吗？</h2><p className="mt-3 text-slate-600">你的原始需求默认仅对自己可见，获得授权并经过脱敏审核后，才可能作为案例分享。</p><Link to="/register" className="inline-block mt-5 text-orange-700 font-medium">创建账号 →</Link></div><img src={brand+'mascot.webp'} className="max-h-64 mx-auto object-contain" alt="工作坊吉祥物"/></section></main><footer className="border-t py-7 text-center text-sm text-slate-500">Powered by 杰哥AI工作坊 · Jack Cases</footer></div>;}
function Auth({onLogin}:{onLogin:()=>void}){const nav=useNavigate();const[mode,setMode]=useState<'login'|'register'>(window.location.pathname==='/register'?'register':'login'),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[key,setKey]=useState(''),[error,setError]=useState('');useEffect(()=>setMode(window.location.pathname==='/register'?'register':'login'),[window.location.pathname]);return <div className="min-h-screen lg:grid lg:grid-cols-2 bg-white"><div className="hidden lg:flex relative bg-orange-50 p-12 flex-col justify-between overflow-hidden"><Link to="/" className="font-semibold text-slate-700">← 返回官网</Link><img src={brand+'mascot.webp'} className="w-full max-w-xl mx-auto rounded-3xl object-cover max-h-[72vh]" alt="平台登录配图"/><p className="text-center text-slate-600">分享真实需求，发现更多业务场景。</p></div><div className="grid place-items-center p-6"><Card className="w-full max-w-md border-0 shadow-none lg:border lg:shadow-sm"><CardContent className="space-y-5"><Link to="/" className="text-sm text-orange-600 lg:hidden">← 返回官网</Link><div><img src={brand+'mascot.webp'} className="h-16 w-16 object-cover object-top bg-orange-50 rounded-full mb-3" alt="平台头像"/><h1 className="text-2xl font-bold">医疗大健康及医药领域需求平台</h1><p className="text-slate-500 text-sm mt-1">医药流通 · 医院与健康服务 · IVD · {mode==='login'?'登录账号':'创建账号'}</p></div>{key?<div className="space-y-3"><h2 className="font-semibold">注册成功，请保存 API Key</h2><p className="text-sm text-slate-500">密钥有效期 30 天，仅供普通 Agent 使用。登录后可在 Agent 技能页再次复制或更换。</p><div className="bg-slate-100 rounded-md p-3 text-xs break-all">{key}</div><Button onClick={async()=>{setError('');try{await copyText(key);}catch(e){setError(errorMessage(e));}}} variant="outline">复制密钥</Button><Button className="w-full" onClick={onLogin}>进入平台</Button><ErrorLine error={error}/></div>:<form className="space-y-3" onSubmit={async e=>{e.preventDefault();setError('');try{const data=await post('/auth/'+mode,{email,password});if(data.apiKey)setKey(data.apiKey);else onLogin();}catch(e:any){setError(errorMessage(e));}}}><label htmlFor="auth-email" className="block text-sm font-medium">邮箱</label><Input id="auth-email" name="email" autoComplete="email" aria-describedby={error?'auth-error':undefined} type="email" required placeholder="邮箱" value={email} onChange={e=>setEmail(e.target.value)}/><label htmlFor="auth-password" className="block text-sm font-medium">密码（至少 6 位）</label><Input id="auth-password" name="password" autoComplete={mode==='login'?'current-password':'new-password'} aria-describedby={error?'auth-error':undefined} type="password" required minLength={6} placeholder="密码（至少 6 位）" value={password} onChange={e=>setPassword(e.target.value)}/>{error&&<p id="auth-error" role="alert" className="text-red-600 text-sm">{error}</p>}<Button className="w-full !bg-orange-500 hover:!bg-orange-600">{mode==='login'?'登录':'创建账号'}</Button><button type="button" className="text-sm text-orange-600 hover:underline" onClick={()=>{const next=mode==='login'?'register':'login';setMode(next);setError('');nav('/'+next)}}>{mode==='login'?'没有账号？注册':'已有账号？登录'}</button></form>}</CardContent></Card></div></div>;}
function Shell({user,onLogout,admin,children}:{user:User;onLogout:()=>void;admin:boolean;children:React.ReactNode}){const canEditTaxonomy=['admin','super_admin'].includes(user.role);const menus=admin?[['/admin','数据概览',LayoutDashboard],['/admin/requirements','需求管理',ClipboardList],['/admin/cases','案例管理',BookOpen],['/admin/media','图片与资料',Images],['/admin/users','用户管理',Users],['/admin/categories','分类管理',FolderTree],['/admin/tags','标签管理',FolderTree],...(canEditTaxonomy?[[ '/admin/skill','管理 Agent 技能',Bot] as const]:[])]as const:[['/','探索案例',BookOpen],['/submit','提交需求',Plus],['/mine','我的需求',ClipboardList],['/keys','Agent 技能',Bot]]as const;
 const links=menus.map(([href,label])=><NavLink key={href} end={href==='/'||href==='/admin'} to={href} className={({isActive})=>'block rounded-md px-3 py-2.5 text-sm '+(isActive?'bg-orange-50 font-semibold text-orange-700':'text-slate-700 hover:bg-slate-50')}>{label}</NavLink>);
 const account=<><span className="block max-w-56 truncate px-3 text-xs text-slate-600">{user.email}</span>{admin?<Link className="block px-3 py-2 text-sm text-orange-700" to="/">学员端</Link>:['admin','super_admin','reviewer'].includes(user.role)&&<Link className="block px-3 py-2 text-sm text-orange-700" to="/admin">管理端</Link>}<button className="flex items-center gap-2 px-3 py-2 text-sm text-slate-700" onClick={onLogout}><LogOut size={16}/>退出登录</button></>;
 return <div className="min-h-screen bg-[#f8fafc]"><header className="sticky top-0 z-20 border-b bg-white"><div className="mx-auto flex min-h-16 max-w-7xl flex-wrap items-center justify-between gap-3 px-4 py-3 md:px-6"><Link className="flex items-center gap-2 text-base font-bold" to="/"><img src={brand+'mascot.webp'} className="h-9 w-9 rounded-full bg-orange-50 object-cover object-top" alt="平台头像"/>医疗大健康需求平台</Link>{!admin&&<nav aria-label="平台导航" className="hidden items-center md:flex">{links}</nav>}<div className="hidden items-center gap-1 md:flex">{account}</div><MobileNavigation label={admin?'管理菜单':'平台导航'}>{links}<div className="mt-2 space-y-1 border-t pt-2">{account}</div></MobileNavigation></div></header><div className={'mx-auto max-w-7xl min-h-[calc(100vh-4rem)] '+(admin?'flex':'')}>{admin&&<aside className="hidden w-52 shrink-0 border-r bg-white p-3 md:block"><nav aria-label="管理导航" className="space-y-1">{links}</nav></aside>}<main className="min-w-0 flex-1 p-4 md:p-8">{children}</main></div></div>;
}
type Category={id:string;parentId:string|null;name:string;slug:string;sortOrder:number};
function TagSelector({value,onChange,retained=[]}:{value:string[];onChange:(v:string[])=>void;retained?:Tag[]}){const lookupQuery=useData<Tag[]>('tags','/tags');const{data:tags=[]}=lookupQuery;return <div className="space-y-2"><p className="text-sm font-medium">标签（最多 12 个）</p><QueryFeedback query={lookupQuery}/><div className="flex flex-wrap gap-2">{[...tags,...retained.filter(t=>!t.active&&value.includes(t.id)&&!tags.some(x=>x.id===t.id))].map(t=><button type="button" key={t.id} onClick={()=>onChange(value.includes(t.id)?value.filter(x=>x!==t.id):value.length<12?[...value,t.id]:value)} className={'rounded-full border px-3 py-1 text-xs '+(value.includes(t.id)?'bg-orange-100 border-orange-400 text-orange-800':'bg-white text-slate-600')}>{t.name}</button>)}</div></div>;}
function AdminTags({editable=true}:{editable?:boolean}){const privateQc=useQueryClient();const qc={invalidateQueries:()=>{void publicClient.invalidateQueries();void privateQc.invalidateQueries();}};const lookupQuery=useData<Tag[]>('admin-tags',editable?'/tags?scope=all':'/tags');const{data:tags=[],error:loadError}=lookupQuery;const[name,setName]=useState(''),[slug,setSlug]=useState(''),[group,setGroup]=useState('general'),[color,setColor]=useState('orange'),[error,setError]=useState('');return <Panel title="标签管理"><QueryFeedback query={lookupQuery}/>{editable&&<Card><CardContent className="space-y-3"><p className="font-medium">创建标签</p><div className="flex flex-wrap gap-2"><Input className="sm:w-40" placeholder="名称" value={name} onChange={e=>setName(e.target.value)}/><Input className="sm:w-40" placeholder="slug" value={slug} onChange={e=>setSlug(e.target.value)}/><Input className="sm:w-36" placeholder="分组" value={group} onChange={e=>setGroup(e.target.value)}/><select className="border rounded-md px-3" value={color} onChange={e=>setColor(e.target.value)}>{['orange','blue','green','purple','gray'].map(c=><option key={c}>{c}</option>)}</select><Button onClick={async()=>{try{await post('/tags',{name,slug,group,color});setName('');setSlug('');setError('');qc.invalidateQueries()}catch(e:any){setError(errorMessage(e))}}}>新建标签</Button></div><ErrorLine error={error}/></CardContent></Card>}<div className="space-y-2">{tags.map(t=><Card key={t.id}><CardContent className="flex flex-wrap items-center justify-between gap-3"><div className="text-sm"><b>{t.name}</b><span className="ml-3 text-slate-400">/{t.slug} · {t.group} · {t.color} · {t.sortOrder}</span></div>{editable&&<div className="flex gap-2"><Button size="sm" variant="outline" onClick={async()=>{const name=prompt('标签名称',t.name);if(!name)return;const slug=prompt('slug',t.slug);if(!slug)return;const group=prompt('分组',t.group);if(group===null)return;const color=prompt('颜色：orange/blue/green/purple/gray',t.color);if(!color)return;const sortOrder=Number(prompt('排序值',String(t.sortOrder))??t.sortOrder);try{await patch('/tags/'+t.id,{name,slug,group,color,sortOrder});qc.invalidateQueries()}catch(e:any){setError(errorMessage(e))}}}>编辑</Button><Button size="sm" variant="outline" onClick={async()=>{try{if(t.active)await patch('/tags/'+t.id,{active:false});else await patch('/tags/'+t.id,{active:true});qc.invalidateQueries()}catch(e:any){setError(errorMessage(e))}}}>{t.active?'停用':'启用'}</Button><Button size="sm" variant="outline" onClick={async()=>{try{if(!confirm('删除此标签？已关联的标签会被停用并保留历史记录。'))return;await api('/tags/'+t.id,{method:'DELETE'});qc.invalidateQueries()}catch(e:any){setError(errorMessage(e))}}}>删除</Button></div>}</CardContent></Card>)}</div></Panel>;}
function Catalog(){const lookupQuery=useData<Category[]>('categories','/categories');const{data:categoryData}=lookupQuery;const secondaryQuery=useData<Tag[]>('catalog-tags','/tags');const{data:tagData}=secondaryQuery;const categories=categoryData??[],tags=tagData??[];const{state,filter,setFilter,update,changeView,clear,returnTo}=useCatalogState({categoryIds:categoryData?.map(c=>c.id),tagIds:tagData?.map(t=>t.id)});const{categoryId:selected,industry:industryFilter,difficulty:diffFilter,implementationStatus:statusFilter,tagIds:tagFilter}=state;const grid=state.view==='grid';const group=categories.filter(c=>!c.parentId).sort((a,b)=>a.sortOrder-b.sortOrder);const{items:shown,isLoading,error,total,controls,industries,allTotal}=useCatalogResults<Case>(state,update);return <div className="space-y-6"><div className="relative overflow-hidden rounded-2xl border border-orange-100 bg-[#fff2e2] px-6 py-7 md:px-10 md:py-9 flex items-center justify-between gap-4"><div className="relative z-10 max-w-lg"><span className="text-xs font-semibold text-orange-700">医疗大健康需求平台 · 需求案例库</span><h1 className="text-2xl md:text-3xl font-bold mt-2">发现医疗大健康领域的真实需求</h1><p className="text-sm text-slate-600 mt-3 leading-relaxed">涵盖医药流通、医院与健康服务、IVD 等场景。浏览经授权审核的参考案例，下载材料，与 AI 一起探索需求。</p><Link to="/submit" className="inline-flex mt-5 rounded-lg bg-orange-500 text-white px-4 py-2.5 text-sm font-medium hover:bg-orange-600">＋ 提交我的需求</Link></div><img src={brand+'mascot.webp'} alt="工作坊吉祥物" className="hidden sm:block w-40 md:w-56 h-44 md:h-52 object-contain object-bottom self-end -mb-9"/></div><div className="flex flex-col md:flex-row gap-6"><aside className="md:w-56 shrink-0"><div className="bg-white rounded-xl border p-3 md:sticky md:top-24"><h2 className="font-semibold text-sm px-3 py-2 mb-2">需求分类</h2><button aria-pressed={!selected} onClick={()=>update({categoryId:''})} className={'w-full text-left rounded-lg px-3 py-2 text-sm '+(!selected?'bg-orange-50 text-orange-700 font-semibold':'hover:bg-slate-50 text-slate-600')}>全部案例 <span className="float-right text-xs opacity-60">{allTotal}</span></button>{group.map(parent=><div key={parent.id} className="mt-2"><button aria-pressed={selected===parent.id} onClick={()=>update({categoryId:parent.id})} className={'w-full text-left rounded-lg px-3 py-2 text-sm font-medium '+(selected===parent.id?'bg-orange-50 text-orange-700':'text-slate-700 hover:bg-slate-50')}>{parent.name}</button>{categories.filter(x=>x.parentId===parent.id).map(child=><button key={child.id} aria-pressed={selected===child.id} onClick={()=>update({categoryId:child.id})} className={'block w-full text-left pl-6 pr-2 py-1.5 rounded-md text-xs '+(selected===child.id?'bg-orange-50 text-orange-700 font-medium':'text-slate-500 hover:bg-slate-50')}>{child.name}</button>)}</div>)}{!lookupQuery.isPending&&!lookupQuery.error&&categories.length===0&&<p className="text-xs text-slate-400 px-3 py-3">分类正在整理中</p>}</div></aside><div className="flex-1 min-w-0 space-y-4"><div className="bg-white rounded-xl border p-3 flex gap-3"><div className="relative flex-1"><Search size={16} className="absolute left-3 top-3 text-slate-400"/><Input className="pl-9 border-slate-200" aria-label="搜索业务场景、行业、案例名称" placeholder="搜索业务场景、行业、案例名称" value={filter} onChange={e=>setFilter(e.target.value)}/></div><div className="flex border rounded-lg overflow-hidden"><button title="网格视图" aria-label="网格视图" aria-pressed={grid} onClick={()=>changeView(true)} className={'px-3 '+(grid?'bg-orange-50 text-orange-600':'text-slate-500')}><Grid2X2 size={17}/></button><button title="列表视图" aria-label="列表视图" aria-pressed={!grid} onClick={()=>changeView(false)} className={'px-3 '+(!grid?'bg-orange-50 text-orange-600':'text-slate-500')}><ListIcon size={17}/></button></div></div><div className="bg-white border rounded-xl p-3 flex flex-wrap gap-2"><select aria-label="行业" value={industryFilter} onChange={e=>update({industry:e.target.value})} className="border rounded-md p-2 text-sm"><option value="">全部行业</option>{industries.map(x=><option key={x}>{x}</option>)}</select><select aria-label="难度" className="border rounded-md p-2 text-sm" value={diffFilter} onChange={e=>update({difficulty:e.target.value})}><option value="">全部难度</option><option value="easy">简单</option><option value="medium">中等</option><option value="hard">复杂</option></select><select aria-label="实现状态" className="border rounded-md p-2 text-sm" value={statusFilter} onChange={e=>update({implementationStatus:e.target.value})}><option value="">全部状态</option><option value="pending">待实现</option><option value="building">开发中</option><option value="completed">已实现</option><option value="verified">已验证</option></select><button className="text-xs text-orange-600" onClick={clear}>清除筛选</button><div className="w-full flex flex-wrap gap-2">{tags.map(t=><button key={t.id} aria-pressed={tagFilter.includes(t.id)} onClick={()=>update({tagIds:tagFilter.includes(t.id)?tagFilter.filter(x=>x!==t.id):[...tagFilter,t.id]})} className={'rounded-full px-3 py-1 text-xs border '+(tagFilter.includes(t.id)?'bg-orange-100 border-orange-400':'bg-white')}>{t.name}</button>)}</div></div><div className="flex items-center justify-between"><h2 className="font-semibold">{selected?categories.find(c=>c.id===selected)?.name||'分类案例':'全部案例'}</h2><span className="text-xs text-slate-500">{total} 个案例</span></div><QueryFeedback query={lookupQuery}/><QueryFeedback query={secondaryQuery}/>{controls}{isLoading?<p className="text-sm text-slate-500">载入案例中...</p>:error?null:shown.length?<div className={grid?'grid sm:grid-cols-2 xl:grid-cols-3 gap-4':'space-y-3'}>{shown.map(c=><Link to={'/cases/'+c.id+'?'+new URLSearchParams({returnTo})} key={c.id} className={'requirement-card '+(!grid?'catalog-list-card':'')}><RequirementCover title={c.title} code={c.requirementCode} industry={c.industry} image={coverImage(c.images,c.coverMediaId)}/><div className="requirement-card-body"><div className="requirement-card-meta"><span>{categories.find(x=>x.id===c.categoryId)?.name||c.industry||'医疗大健康'}</span><span>{c.requirementCode||'参考案例'} · {c.contentVersion||'v1.0'}</span></div><h3>{c.title}</h3><div className="mt-2 flex flex-wrap gap-1">{c.tags?.map(t=><span key={t.id} className="rounded bg-orange-50 px-2 py-0.5 text-xs text-orange-800">{t.name}</span>)}</div><p>{plainSummary(c.summary)}</p><div className="requirement-card-bottom"><span>查看需求与配套材料</span><ChevronRight size={16}/></div></div></Link>)}</div>:<div className="bg-white border rounded-xl py-10 text-center"><img src={brand+'empty.webp'} alt="暂无匹配的案例" className="mx-auto w-44 h-44 object-contain"/><p className="text-sm text-slate-500 mt-2">暂无匹配案例，试试其他分类或关键词。</p><Link to="/submit" className="inline-block mt-3 text-sm text-orange-700">提交一个需求 →</Link></div>}</div></div></div>;}

function CaseDetail(){
 const location=useLocation();const returnTo=catalogReturnPath(new URLSearchParams(location.search).get('returnTo'));
 const{id}=useParams();const detailQuery=useData<Case>('case','/cases/'+id);const{data}=detailQuery;const lookupQuery=useData<Category[]>('detail-categories','/categories');const{data:categories=[]}=lookupQuery;const[done,setDone]=useState(''),[copyError,setCopyError]=useState('');
 if(!data)return <QueryFeedback query={detailQuery} label="需求详情"/>;
 const body=data.publicContent??data.prompts?.find(p=>p.type==='requirement')?.content??data.summary;
 const copy=async(type:string)=>{const text=data.prompts?.find(p=>p.type===type)?.content??body;setDone('');setCopyError('');try{await copyText(text);}catch(e){setCopyError(errorMessage(e));return;}setDone(type);await post('/cases/'+id+'/copy-events',{type:type==='build'?'copy_build':'copy_requirement'}).catch(()=>{});setTimeout(()=>setDone(''),1500);};
 return <><QueryFeedback query={detailQuery}/><QueryFeedback query={lookupQuery}/><RequirementDetailLayout backTo={returnTo} id={data.id} title={data.title} code={data.requirementCode} version={data.contentVersion} industry={data.industry} department={data.department} status={data.status} difficulty={data.difficulty} category={categories.find(c=>c.id===data.categoryId)?.name} summary={plainSummary(data.summary,100)} images={data.images??[]} coverId={data.coverMediaId} files={data.files??[]} caseView><ErrorLine error={copyError}/><Markdown content={body||'需求正文待补充。'}/><div className="mt-7 border-t pt-5"><Button variant="outline" onClick={()=>copy('requirement')}>{done==='requirement'?<Check size={16}/>:<Copy size={16}/>}复制需求正文</Button>{data.prompts?.some(p=>p.type==='build'&&p.content)&&<details className="mt-5 rounded-lg border p-4"><summary className="cursor-pointer text-sm font-medium">查看候选搭建提示词</summary><div className="mt-4 space-y-4"><p className="text-xs text-slate-500">参考思路需结合实际场景确认。</p><Markdown content={data.prompts.find(p=>p.type==='build')?.content??''}/><Button size="sm" variant="outline" onClick={()=>copy('build')}>{done==='build'?'已复制':'复制搭建提示词'}</Button></div></details>}</div></RequirementDetailLayout></>;

}
function PrivateRequirementDetail(){
 const{id}=useParams();const detailQuery=useData<Requirement>('requirement-detail','/requirements/'+id);const{data}=detailQuery;const lookupQuery=useData<Category[]>('detail-categories','/categories');const{data:categories=[]}=lookupQuery;
 if(!data)return <QueryFeedback query={detailQuery} label="需求详情"/>;
 return <><QueryFeedback query={detailQuery}/><QueryFeedback query={lookupQuery}/><RequirementDetailLayout id={data.id} title={data.title} code={data.requirementCode} version={data.contentVersion} industry={data.industry} department={data.department} status={data.status} difficulty={data.difficulty} category={categories.find(c=>c.id===data.categoryId)?.name} summary={plainSummary(data.content,100)} images={data.images} coverId={data.coverMediaId} files={data.files??[]} editor={<MyRequirementEditor key={data.id+'-'+data.contentVersion} item={data}/>}><Markdown content={data.content}/></RequirementDetailLayout></>;
}
function Submit({editing}:{editing?:Requirement}){const[coverId,setCoverId]=useState<string|null>(editing?.coverMediaId??null);const qc=useQueryClient();const[saving,setSaving]=useState(false);const[materials,setMaterials]=useState<Material[]>(editing?.files??[]),[fileBusy,setFileBusy]=useState(false),[preview,setPreview]=useState(false),[version,setVersion]=useState(editing?.contentVersion??'v1.0');const nav=useNavigate();const lookupQuery=useData<Category[]>('submit-categories','/categories');const{data:categories=[]}=lookupQuery;const secondaryQuery=useData<any[]>('submit-keys','/keys');const{data:keys=[]}=secondaryQuery;const activeKey=keys.find(k=>ordinaryKey(k)&&!k.legacy);const[method,setMethod]=useState<'skill'|'form'>(editing?'form':'skill'),[copied,setCopied]=useState(false);const[title,setTitle]=useState(editing?.title??''),[content,setContent]=useState(editing?.content??''),[consent,setConsent]=useState(editing?.shareConsent??false),[photos,setPhotos]=useState<{id:string;url:string}[]>(editing?.images??[]),[error,setError]=useState(''),[imageBusy,setImageBusy]=useState(false),[categoryId,setCategoryId]=useState(editing?.categoryId??''),[industry,setIndustry]=useState(editing?.industry??''),[department,setDepartment]=useState(editing?.department??''),[difficulty,setDifficulty]=useState(editing?.difficulty??''),[implementationStatus,setImplementationStatus]=useState(editing?.implementationStatus??'pending'),[expectedOutcome,setExpectedOutcome]=useState(editing?.expectedOutcome??''),[tagIds,setTagIds]=useState<string[]>(editing?.tags?.map(t=>t.id)??[]);const submitLock=React.useRef(false);
 const local=useLocalDraft(editing?'edit:'+editing.id:'new',{title,content,materials,version,consent,photos,categoryId,industry,department,difficulty,implementationStatus,expectedOutcome,tagIds,coverId},d=>{setTitle(d.title??'');setContent(d.content??'');setMaterials(d.materials??[]);setVersion(d.version??'v1.0');setConsent(d.consent??false);setPhotos(d.photos??[]);setCategoryId(d.categoryId??'');setIndustry(d.industry??'');setDepartment(d.department??'');setDifficulty(d.difficulty??'');setImplementationStatus(d.implementationStatus??'pending');setExpectedOutcome(d.expectedOutcome??'');setTagIds(d.tagIds??[]);setCoverId(d.coverId??null);setMethod('form');},saving||imageBusy||fileBusy);return <Panel title={editing?'编辑我的需求':'提交企业需求'}><QueryFeedback query={lookupQuery}/><QueryFeedback query={secondaryQuery}/><div className="space-y-4">{local.controls}{editing?<><RequirementDownloads id={editing.id} code={editing.requirementCode} version={editing.contentVersion}/><p className="text-sm text-slate-600">正文变化后自动递增内容版本，业务编号保持不变。保存不会提交审核，请返回“我的需求”点击“重新提交审核”。</p></>:null}<Tabs hideTabs={!!editing} label="提交方式" items={[{value:'skill',label:'方法一：复制技能提示词'},{value:'form',label:'方法二：手动填写表单'}]} value={method} onChange={value=>setMethod(value as 'skill'|'form')}>{method==='skill'?<Card><CardContent className="space-y-4"><div><h2 className="font-semibold">把提交需求能力交给 Agent</h2><p className="mt-1 text-sm text-slate-500">技能提示词包含当前 API Key 明文，请只粘贴给你信任的 Agent。只读密钥无法提交需求；权限和期限可在 Agent 技能页查看。</p></div>{secondaryQuery.isPending||secondaryQuery.error?null:activeKey?.secretValue?<><pre className="whitespace-pre-wrap break-words rounded-lg bg-slate-50 p-4 text-sm leading-relaxed">{agentSkillText(activeKey.secretValue,activeKey)}</pre><Button onClick={async()=>{setCopied(false);setError('');try{await copyText(agentSkillText(activeKey.secretValue,activeKey));}catch(e){setError(errorMessage(e));return;}setCopied(true);setTimeout(()=>setCopied(false),1500);}}>{copied?<Check size={16}/>:<Copy size={16}/>} {copied?'已复制':'复制技能提示词'}</Button><ErrorLine error={error}/></>:<p className="text-sm text-amber-700">当前密钥无法读取明文。请先到 <Link className="font-medium underline" to="/keys">Agent 技能</Link> 更换 API Key，再复制提示词。</p>}</CardContent></Card>:<Card><CardContent><form className="space-y-5" onSubmit={async e=>{e.preventDefault();if(submitLock.current||imageBusy||fileBusy||local.unresolved)return;submitLock.current=true;setError('');setSaving(true);try{const payload={title,content,fileIds:materials.map(f=>f.id),...(!editing?{contentVersion:version}:{}),shareConsent:consent,categoryId:categoryId||null,industry:industry||null,department:department||null,difficulty:difficulty||null,implementationStatus,expectedOutcome:expectedOutcome||null,tagIds,mediaIds:photos.map(x=>x.id),coverMediaId:coverId};if(editing)await patch('/requirements/'+editing.id,payload);else await post('/requirements',payload);await qc.invalidateQueries({queryKey:['requirements']});local.complete();nav('/mine');}catch(e:any){setError(errorMessage(e));}finally{submitLock.current=false;setSaving(false);}}}><fieldset disabled={saving||local.unresolved} className="space-y-5"><label className="block space-y-2 text-sm font-medium">需求标题<Input required minLength={2} value={title} onChange={e=>setTitle(e.target.value)} placeholder="如：IVD 试剂临期识别与处理跟踪"/></label><label className="block space-y-2 text-sm font-medium">业务需求描述<Textarea required minLength={5} maxLength={40000} rows={7} value={content} onChange={e=>setContent(e.target.value)} placeholder="支持 Markdown：使用 # 标题、- 列表、**重点** 等格式描述业务背景和预期效果。"/></label><div className="space-y-3"><Button type="button" variant="outline" onClick={()=>setPreview(!preview)}>{preview?'收起预览':'预览 Markdown'}</Button>{preview&&<Markdown content={content||'正文待补充'}/>}<label className="block text-sm">{editing?'当前内容版本（修改正文后自动递增）':'内容版本（业务编号提交后自动生成）'}<Input disabled={!!editing} value={version} pattern="v[0-9]+(\.[0-9]+){0,2}" onChange={e=>setVersion(e.target.value)}/></label></div><div className="grid sm:grid-cols-2 gap-3"><label className="text-sm">业务分类<select className="w-full mt-2 border rounded-md p-2" value={categoryId} onChange={e=>setCategoryId(e.target.value)}><option value="">请选择分类</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="text-sm">所属行业<Input placeholder="如：医药流通、IVD、医院服务" value={industry} onChange={e=>setIndustry(e.target.value)}/></label><label className="text-sm">使用部门<Input placeholder="如：采购部" value={department} onChange={e=>setDepartment(e.target.value)}/></label><label className="text-sm">实现难度<select className="w-full mt-2 border rounded-md p-2" value={difficulty} onChange={e=>setDifficulty(e.target.value)}><option value="">未评估</option><option value="easy">简单</option><option value="medium">中等</option><option value="hard">复杂</option></select></label><label className="text-sm">实现状态<select className="w-full mt-2 border rounded-md p-2" value={implementationStatus} onChange={e=>setImplementationStatus(e.target.value)}><option value="pending">待实现</option><option value="building">开发中</option><option value="completed">已实现</option><option value="verified">已验证</option></select></label></div><label className="block text-sm">预期效果<Textarea className="mt-2" value={expectedOutcome} onChange={e=>setExpectedOutcome(e.target.value)} placeholder="希望达到的业务成果"/></label><TagSelector value={tagIds} onChange={setTagIds} retained={editing?.tags}/><Materials value={materials} onChange={setMaterials} onBusy={setFileBusy}/><ImageEditor images={photos} coverId={coverId} onChange={(images,cover)=>{setPhotos(images);setCoverId(cover);}} onBusy={setImageBusy}/><label className="flex items-start gap-2 text-sm text-slate-700"><input type="checkbox" className="mt-1" checked={consent} onChange={e=>setConsent(e.target.checked)}/><span>允许平台在脱敏和人工审核后，将本需求整理为公开案例。未勾选则仅作为私有需求保存。</span></label>{error&&<p className="text-red-600">{error}</p>}<div className="flex flex-wrap gap-3"><Button disabled={imageBusy||fileBusy||saving}>{saving?'保存中…':editing?'保存修改':'提交需求'}</Button>{editing&&<Link to="/mine"><Button type="button" variant="outline">取消</Button></Link>}</div></fieldset></form></CardContent></Card>}</Tabs></div></Panel>;}

function ResubmitRequirement({item}:{item:Requirement}){
 const qc=useQueryClient();const[busy,setBusy]=useState(false),[error,setError]=useState('');
 if(item.status!=='rejected')return null;
 return <div className="space-y-2"><Button type="button" size="sm" disabled={busy} onClick={async()=>{setBusy(true);setError('');try{await post('/requirements/'+item.id+'/resubmit',{});await Promise.all([qc.invalidateQueries({queryKey:['requirements']}),qc.invalidateQueries({queryKey:['requirement-detail']})]);}catch(e:any){setError(errorMessage(e));}finally{setBusy(false);}}}>{busy?'提交中…':'重新提交审核'}</Button><ErrorLine error={error}/></div>;
}
function MyRequirementEditor({item}:{item:Requirement}){
 return <div className="space-y-4"><ReviewHistory item={item}/>{item.status==='rejected'&&<div className="rounded-lg bg-amber-50 p-4 text-sm text-amber-900"><p className="font-medium">退回原因</p><p className="mt-2 whitespace-pre-wrap">{item.reviews?.find(r=>r.decision==='reject')?.notes||'历史记录未填写原因，请联系管理员补充。'}</p><p className="mt-2">请先编辑并保存修改，再重新提交审核。</p></div>}{['submitted','rejected'].includes(item.status)?<Link to={'/mine/'+item.id+'/edit'}><Button variant="outline">编辑需求正文与材料</Button></Link>:<p className="text-sm text-slate-500">当前需求不可修改。</p>}<ResubmitRequirement item={item}/></div>;
}
function CaseImages({item}:{item:Case}){
 const qc=useQueryClient();const[photos,setPhotos]=useState<RequirementImage[]>(item.images??[]),[coverId,setCoverId]=useState(item.coverMediaId??null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState('');
 const{data:source}=useQuery<Requirement>({queryKey:['case-source-images',item.requirementId],queryFn:()=>api('/requirements/'+item.requirementId),enabled:!!item.requirementId});
 return <section className="space-y-4 rounded-lg border p-4"><ImageEditor images={photos} coverId={coverId} onChange={(images,cover)=>{setPhotos(images);setCoverId(cover);setNotice('');}} onBusy={setBusy} available={source?.images}/><p className="text-xs text-slate-500">保存即确认这些图片已审核；仅在该案例发布期间对其他登录用户可见。移除图片不会删除原始需求图片。</p><Button type="button" variant="outline" disabled={busy} onClick={async()=>{setError('');try{await api('/cases/'+item.id+'/images',{method:'PUT',body:JSON.stringify({mediaIds:photos.map(im=>im.id),coverMediaId:coverId})});await Promise.all([qc.invalidateQueries({queryKey:['case']}),qc.invalidateQueries({queryKey:['cases']})]);setNotice('封面与详情图片已保存');}catch(err:any){setError(errorMessage(err));}}}>保存图片审核</Button><ErrorLine error={error}/>{notice&&<p role="status" className="text-sm text-green-700">{notice}</p>}</section>;
}

function CaseMaterials({item}:{item:Case}){
 const qc=useQueryClient();const[value,setValue]=useState(item.files??[]),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState('');
 return <div className="space-y-3 rounded-md border p-3"><Materials value={value} onChange={v=>{setValue(v);setNotice('');}} onBusy={setBusy} review/><p className="text-xs text-slate-500">资料单独保存；勾选后仅在此案例发布期间可供登录用户下载。</p><Button type="button" variant="outline" disabled={busy} onClick={async()=>{setError('');try{await api('/cases/'+item.id+'/files',{method:'PUT',body:JSON.stringify({files:value.map(f=>({id:f.id,approved:f.approved??false}))})});await qc.invalidateQueries({queryKey:['case']});setNotice('案例资料审核已保存');}catch(err:any){setError(errorMessage(err));}}}>保存资料审核</Button><ErrorLine error={error}/>{notice&&<p role="status" className="text-sm text-green-700">{notice}</p>}</div>;
}

