function AdminCategories({editable=true}:{editable?:boolean}){const query=useData<any[]>('categories','/categories');const{data=[],error}=query;const qc=publicClient;const[name,setName]=useState(''),[slug,setSlug]=useState(''),[parentId,setParentId]=useState(''),[sortOrder,setSortOrder]=useState(0),[editingId,setEditingId]=useState<string|null>(null),[actionError,setActionError]=useState('');const reset=()=>{setName('');setSlug('');setParentId('');setSortOrder(0);setEditingId(null)};return <Panel title="分类管理"><QueryFeedback query={query} emptyLabel="暂无分类记录。"/>{editable&&<Card><CardContent className="flex flex-wrap gap-3"><Input className="sm:w-44" placeholder="分类名称" value={name} onChange={e=>setName(e.target.value)}/><Input className="sm:w-44" placeholder="英文 slug" value={slug} onChange={e=>setSlug(e.target.value)}/><select className="border rounded-md px-3" value={parentId} onChange={e=>setParentId(e.target.value)}><option value="">一级分类</option>{data.filter(c=>c.id!==editingId).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><Input className="sm:w-24" type="number" aria-label="排序值" value={sortOrder} onChange={e=>setSortOrder(Number(e.target.value))}/><Button onClick={async()=>{try{if(editingId)await patch('/categories/'+editingId,{name,slug,parentId:parentId||null,sortOrder});else await post('/categories',{name,slug,parentId:parentId||null,sortOrder});reset();setActionError('');qc.invalidateQueries()}catch(e:any){setActionError(errorMessage(e))}}}>{editingId?'保存分类':'添加分类'}</Button>{editingId&&<Button variant="outline" onClick={reset}>取消</Button>}</CardContent></Card>}<ErrorLine error={actionError}/><div className="space-y-2">{data.map(c=><div key={c.id} className="bg-white border rounded-md p-3 text-sm flex flex-wrap items-center justify-between gap-2"><span>{c.parentId?'— ':''}{c.name} <span className="text-slate-400">/{c.slug} · {c.sortOrder}</span></span>{editable&&<div className="flex gap-2"><Button size="sm" variant="outline" onClick={()=>{setEditingId(c.id);setName(c.name);setSlug(c.slug);setParentId(c.parentId??'');setSortOrder(c.sortOrder);setActionError('');window.scrollTo(0,0)}}>编辑</Button><Button size="sm" variant="outline" onClick={async()=>{try{if(!confirm('删除此分类？被需求、案例或子分类使用时无法删除。'))return;await api('/categories/'+c.id,{method:'DELETE'});qc.invalidateQueries()}catch(e:any){setActionError(errorMessage(e))}}}>删除</Button></div>}</div>)}</div></Panel>;}
function AdminSkill(){
 const qc=useQueryClient();const lookupQuery=useData<{content:string}>('admin-skill','/admin/skill');const{data:skill,error}=lookupQuery;const secondaryQuery=useData<any[]>('admin-skill-keys','/keys');const{data:keys=[]}=secondaryQuery;
 const activeKey=keys.find(k=>usableKey(k)&&k.scopes?.includes('taxonomy:write')&&k.secretValue);
 const[copied,setCopied]=useState(false),[errorCopy,setErrorCopy]=useState(''),[busy,setBusy]=useState(false),[days,setDays]=useState(30);
 const text=(skill?.content.replace('<管理员自己的 API Key>',activeKey?.secretValue??'<请先生成分类标签管理密钥>')??'')+(activeKey?'\n\n- 权限范围：taxonomy:read、taxonomy:write；无用户管理、审核或发布权限。\n- 到期时间：'+new Date(activeKey.expiresAt*1000).toLocaleString('zh-CN'):'');
 return <Panel title="管理 Agent 技能"><QueryFeedback query={lookupQuery}/><QueryFeedback query={secondaryQuery}/><Card><CardContent className="space-y-4"><p className="text-sm text-slate-600">显式生成仅可维护分类与标签的密钥。不会授予用户管理、需求审核或案例发布权限，也不会替换普通 Agent 密钥。</p><KeyExpiry value={days} onChange={setDays}/><Button disabled={busy||!!error} variant="outline" onClick={async()=>{setBusy(true);setErrorCopy('');try{await post('/keys/taxonomy',{expiresInDays:days});await qc.invalidateQueries();}catch(e:any){setErrorCopy(errorMessage(e));}finally{setBusy(false);}}}>{busy?'正在生成…':'生成 / 更换分类标签管理密钥'}</Button>{lookupQuery.isPending||lookupQuery.error||secondaryQuery.isPending||secondaryQuery.error?null:activeKey?<><p className="text-sm text-slate-700">权限：读取和维护分类与标签；到期：{new Date(activeKey.expiresAt*1000).toLocaleString('zh-CN')}</p><pre className="whitespace-pre-wrap break-all rounded-lg bg-slate-50 p-4 text-sm leading-relaxed">{text}</pre><Button onClick={async()=>{setCopied(false);setErrorCopy('');try{await copyText(text);setCopied(true);setErrorCopy('');setTimeout(()=>setCopied(false),1500);}catch{setErrorCopy('复制失败，请选中文案手动复制。');}}}>{copied?<Check size={16}/>:<Copy size={16}/>} {copied?'已复制':'复制管理技能'}</Button></>:<p className="text-sm text-amber-800">尚无有效的分类标签管理密钥。请先生成，再复制给可信 Agent。</p>}<ErrorLine error={errorCopy}/></CardContent></Card></Panel>;
}
