export default function App(){const qc=useQueryClient();
 const[transition,setTransition]=useState(false),[sessionError,setSessionError]=useState('');
 const session=useQuery<User|null>({queryKey:['me'],queryFn:({signal})=>currentUser<User>(signal),retry:false});
 const{data:user,isLoading,refetch}=session;
 const nav=useNavigate();
 const login=async()=>{setTransition(true);
 await qc.cancelQueries({queryKey:['me']});
 try{const result=await refetch();
 if(!result.error)nav('/');}finally{setTransition(false);}};
 if(transition||isLoading)return <div role="status" className="p-10 text-slate-600">{transition?'正在切换账号…':'正在确认登录状态…'}</div>;
 if(session.error)return <div className="p-10"><h1 className="mb-4 font-semibold">暂时无法确认登录状态</h1><QueryFeedback query={session}/></div>;
 if(!user)return <Routes><Route path="/" element={<Landing/>}/><Route path="/login" element={<Auth onLogin={()=>{void login();}}/>}/><Route path="/register" element={<Auth onLogin={()=>{void login();}}/>}/><Route path="*" element={<Navigate to="/"/>}/></Routes>;
 const logout=async()=>{setTransition(true);setSessionError('');
 try{await qc.cancelQueries({queryKey:['me']});
 await post('/auth/logout',{});qc.setQueryData(['me'],null);nav('/');}catch(e){setSessionError(errorMessage(e));
 await refetch();}finally{setTransition(false);}};
 return <AccountQueries key={user.id+':'+user.role}><DraftUser.Provider value={user.id}><ErrorLine error={sessionError} retry={logout}/><Routes><Route path="/admin/*" element={['admin','super_admin','reviewer'].includes(user.role)?<Shell admin user={user} onLogout={logout}><Routes><Route index element={<Dashboard/>}/><Route path="requirements" element={<Requirements admin/>}/><Route path="cases" element={<AdminCases/>}/><Route path="users" element={<AdminUsers user={user}/>}/><Route path="media" element={<AdminMedia/>}/><Route path="categories" element={<AdminCategories editable={user.role==='admin'||user.role==='super_admin'}/>}/><Route path="tags" element={<AdminTags editable={user.role==='admin'||user.role==='super_admin'}/>}/><Route path="skill" element={user.role==='admin'||user.role==='super_admin'?<AdminSkill/>:<Navigate to="/admin"/>}/></Routes></Shell>:<Navigate to="/"/>}/><Route path="/*" element={<Shell user={user} admin={false} onLogout={logout}><Routes><Route index element={<Catalog/>}/><Route path="cases/:id" element={<CaseDetail/>}/><Route path="submit" element={<Submit/>}/><Route path="mine" element={<Requirements/>}/><Route path="requirements/:id" element={<PrivateRequirementDetail/>}/><Route path="mine/:id/edit" element={<EditMyRequirement/>}/><Route path="keys" element={<Keys/>}/><Route path="*" element={<NotFound/>}/></Routes></Shell>}/></Routes></DraftUser.Provider></AccountQueries>;}

function AccountQueries({children}:{children:React.ReactNode}){const[client]=useState(createPrivateClient);useLayoutEffect(()=>()=>disposePrivateClient(client),[client]);
 return <QueryClientProvider client={client}>{children}</QueryClientProvider>;}
